DROP TABLE IF EXISTS `part_fitments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `part_fitments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `partId` int NOT NULL,
  `vehicleId` int NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `part_fitments_partId_vehicleId_key` (`partId`,`vehicleId`),
  KEY `part_fitments_vehicleId_fkey` (`vehicleId`),
  CONSTRAINT `part_fitments_partId_fkey` FOREIGN KEY (`partId`) REFERENCES `parts` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `part_fitments_vehicleId_fkey` FOREIGN KEY (`vehicleId`) REFERENCES `vehicles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=738 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

