  CONSTRAINT `request_items_locationId_fkey` FOREIGN KEY (`locationId`) REFERENCES `locations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `request_items_partId_fkey` FOREIGN KEY (`partId`) REFERENCES `parts` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `request_items_requestId_fkey` FOREIGN KEY (`requestId`) REFERENCES `requests` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
